@@ -0,0 +1,15 @@
+// Kitchen sites and their storage locations (schema 3).
+import { AppError } from "../errors.js";
+
+/** Checks that `site` is in `store.data.sites` and returns its id. */
+export function checkSite(store, site = "main") {
+  if (!(store.data.sites ?? []).some((s) => s.id === site))
+    throw new AppError("unknown_site", { id: site });
+  return site;
+}
+
+/** True when `location` is a location belonging to `site`. */
+export function locationInSite(store, location, site = "main") {
+  checkSite(store, site);
+  return store.data.locations.some((l) => l.id === location && l.site === site);
+}
